// Returns the index of a minimum element in the suffix a[i..].
// Precondition: i < a.len()
fn look_for_min(a: &[i32], i: usize) -> usize {
    assert!(i < a.len(), "start index i must be within array bounds");

    let mut m = i;
    for j in (i + 1)..a.len() {
        if a[j] < a[m] {
            m = j;
        }
    }
    m
}

