    #[test]
    fn finds_min_in_suffix() {
        let a = [7, 3, 9, 1, 4];
        assert_eq!(look_for_min(&a, 0), 3); // min is 1 at index 3
        assert_eq!(look_for_min(&a, 2), 3); // suffix [9,1,4]
        assert_eq!(look_for_min(&a, 3), 3); // suffix [1,4]
    }

